/** Upgrade/restart coverage using a synthetic save generated by released V3.47 code. */
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {spawnSync} from 'node:child_process';
import {AIAdapter,ENGINE_VERSION} from './ai_adapter.mjs';
import {Client} from '@modelcontextprotocol/sdk/client/index.js';
import {StdioClientTransport} from '@modelcontextprotocol/sdk/client/stdio.js';
const root=path.dirname(fileURLToPath(import.meta.url));
const original=JSON.parse(fs.readFileSync(new URL('./test_fixtures/session_v347.json',import.meta.url)));
assert.equal(original.engineVersion,'3.47.0');
assert.equal(Object.keys(original.game.s.savedMaps).length,2);
assert(original.game.s.scene.artwork.png);
for(const version of ['3.37.0','3.38.0','3.39.0','3.40.0','3.41.0','3.42.0','3.43.0','3.46.0','3.47.0','3.48.0','3.48.1','3.48.2','3.49.0','3.50.0',ENGINE_VERSION]){
 const saved=structuredClone(original);saved.engineVersion=version;
 const before=structuredClone(saved),restored=new AIAdapter({saved});
 assert.deepEqual(saved,before,'Loading must not mutate input');
 assert.deepEqual(restored.snapshot(),{...before,engineVersion:ENGINE_VERSION},'Preserve all state, checkpoints and receipts from '+version);
}
console.log('PASS compatible published save headers retain complete state; current writer can reload');
const dir=fs.mkdtempSync(path.join(os.tmpdir(),'pf-upgrade-'));
const file=path.join(dir,'synthetic.json');
const env=Object.fromEntries(Object.entries(process.env).filter(([k])=>!k.startsWith('TABLETOP_')&&!['NODE_PATH','NODE_OPTIONS','OPENAI_API_KEY','CONTROL_PLANE_API_KEY'].includes(k)));
const connect=async()=>{
 const transport=new StdioClientTransport({command:process.execPath,args:[path.join(root,'mcp_server.mjs')],cwd:root,env:{...env,TABLETOP_STATE_PATH:file},stderr:'pipe'});
 let errors='';transport.stderr.on('data',c=>errors+=c.toString());
 const client=new Client({name:'upgrade-regression',version:'1.0.0'});
 try{await client.connect(transport);}catch(e){await client.close();throw Error(e.message+' '+errors);}
 return client;
};
try{
 const bytes=JSON.stringify(original);fs.writeFileSync(file,bytes);
 let client=await connect();
 try{
  const r=await client.callTool({name:'kernel_status',arguments:{}});assert(!r.isError);
  assert.equal(r.structuredContent.engineVersion,ENGINE_VERSION);
  assert.equal(r.structuredContent.map.savedMapCount,2);
  assert.equal(r.structuredContent.map.width,30);
  assert.equal(r.structuredContent.map.height,40);
  assert.equal(fs.readFileSync(file,'utf8'),bytes,'Startup/status must not rewrite old saves');
  const change=await client.callTool({name:'kernel_gm',arguments:{command:{op:'gm_set_player_view',title:'Synthetic upgraded map'},expectedRevision:r.structuredContent.revision,requestId:'upgrade_once',reason:'Disposable upgrade regression'}});assert(!change.isError,JSON.stringify(change));
 }finally{await client.close();}
 const upgraded=JSON.parse(fs.readFileSync(file));assert.equal(upgraded.engineVersion,ENGINE_VERSION);
 assert.deepEqual(upgraded.game.s.savedMaps,original.game.s.savedMaps);
 assert.deepEqual(upgraded.game.s.scene.artwork,original.game.s.scene.artwork);
 assert.equal(upgraded.game.s.worldRounds,original.game.s.worldRounds);
 client=await connect();try{const r=await client.callTool({name:'kernel_status',arguments:{}});assert(!r.isError);assert.equal(r.structuredContent.map.savedMapCount,2);}finally{await client.close();}
 console.log('PASS actual V3.47 disk save starts MCP, remains untouched on read, persists on mutation and restarts with maps/artwork intact');
 for(const invalid of [{...original,engineVersion:'9.99.0'},{...original,format:'tabletop-kernel-session/2'}]){
  const bytes=JSON.stringify(invalid);fs.writeFileSync(file,bytes);
  const run=spawnSync(process.execPath,[path.join(root,'mcp_server.mjs')],{cwd:root,env:{...env,TABLETOP_STATE_PATH:file},encoding:'utf8',timeout:10000});
  assert.equal(run.status,1);assert.match(run.stderr,/Unsupported session format\/version/);
  assert.equal(fs.readFileSync(file,'utf8'),bytes);assert(!fs.existsSync(file+'.lock'));
 }
 console.log('PASS unsupported future versions/formats fail without changing the file or leaving a lock');
}finally{fs.rmSync(dir,{recursive:true,force:true});}
